const topics=['Spacing','Placement','Proximity','Composition','Typography','Photography','Shapes','Interaction','Information architecture','Patterns','Texture'];
const topic=document.getElementById('topic'),search=document.getElementById('search'),list=document.getElementById('resource-list');
for(const name of topics){const option=document.createElement('option');option.value=name;option.textContent=name;topic.append(option)}
const params=new URLSearchParams(location.search);if(topics.includes(params.get('topic')))topic.value=params.get('topic');search.value=params.get('q')||'';
function draw(){const q=search.value.trim().toLowerCase(),selected=topic.value;const filtered=resources.filter(r=>(!selected||r.topics.includes(selected))&&(!q||`${r.title} ${r.publisher} ${r.topics.join(' ')} ${r.note} ${r.kind}`.toLowerCase().includes(q)));list.innerHTML='';for(const r of filtered){const li=document.createElement('li');li.id=`resource-${r.id}`;li.className='resource-item';const number=document.createElement('span');number.className='num';number.textContent=String(r.id);const info=document.createElement('div'),title=document.createElement('h2'),a=document.createElement('a');a.href=r.url;a.textContent=r.title;title.append(a);const p=document.createElement('p');p.textContent=r.note;const url=document.createElement('a');url.className='resource-url';url.href=r.url;url.textContent=r.url;info.append(title,p,url);const meta=document.createElement('div');meta.className='resource-meta';const kind=document.createElement('span');kind.className='kind';kind.textContent=r.kind;const pub=document.createElement('div');pub.textContent=r.publisher;const tags=document.createElement('div');tags.textContent=r.topics.join(' / ');meta.append(kind,pub,tags);li.append(number,info,meta);list.append(li)}document.getElementById('reading-count').textContent=`${filtered.length} of ${resources.length} resources${selected?' / '+selected:''}`;document.getElementById('empty').hidden=filtered.length>0;const next=new URLSearchParams();if(q)next.set('q',search.value.trim());if(selected)next.set('topic',selected);history.replaceState(null,'',location.pathname+(next.size?'?'+next:'')+location.hash)}
search.addEventListener('input',draw);topic.addEventListener('change',draw);draw();
document.querySelector('.starter-route').addEventListener('click',e=>{if(e.target.closest('a')){search.value='';topic.value='';draw()}});
if(location.hash.startsWith('#resource-'))requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView({block:'start'}));
